def resolve(query_id, accepted):
    if accepted is None:
        return None
    if isinstance(accepted, str) and accepted.startswith("top"):
        return [PREDS[query_id]["top5"][int(accepted[3:]) - 1]["slug"]]
    if isinstance(accepted, str):
        return [accepted]
    return [PREDS[query_id]["top5"][int(a[3:]) - 1]["slug"] if a.startswith("top") else a for a in accepted]


def main():
    seen = set()
    for query_id, decision, accepted, note in DECISIONS:
        assert query_id not in seen, f"duplicate {query_id}"
        seen.add(query_id)
        record(query_id, decision, resolve(query_id, accepted), reviewer="claude", note=note)
    for query_id in TOP1_CHECKED:
        assert query_id not in seen, f"duplicate {query_id}"
        record(query_id, "keep", reviewer="claude", note="топ-1 модели = разметка; этикетка проверена по листу")
    print("recorded", len(DECISIONS) + len(TOP1_CHECKED), "decisions")


if __name__ == "__main__":
    main()
